from django.conf import settings
from django.db import models

from products.models import Categories, Product
from Vendors.models import VendorStore


class ProductDraft(models.Model):
    """A vendor-reviewed listing proposal generated by the AI assistant.

    Nothing is written to the live catalogue until a vendor explicitly
    approves the draft. The draft keeps both the AI suggestion and the
    vendor-edited values so pricing/market context remains auditable.
    """

    STATUS_DRAFT = "draft"
    STATUS_PUBLISHED = "published"
    STATUS_REJECTED = "rejected"
    STATUS_CHOICES = [
        (STATUS_DRAFT, "Draft"),
        (STATUS_PUBLISHED, "Published"),
        (STATUS_REJECTED, "Rejected"),
    ]

    CONDITION_NEW = "new"
    CONDITION_LIKE_NEW = "like_new"
    CONDITION_USED = "used"
    CONDITION_REFURBISHED = "refurbished"
    CONDITION_CHOICES = [
        (CONDITION_NEW, "New"),
        (CONDITION_LIKE_NEW, "Like new"),
        (CONDITION_USED, "Used"),
        (CONDITION_REFURBISHED, "Refurbished"),
    ]

    vendor = models.ForeignKey(
        settings.AUTH_USER_MODEL,
        on_delete=models.CASCADE,
        related_name="ai_product_drafts",
    )
    store = models.ForeignKey(
        VendorStore,
        on_delete=models.CASCADE,
        related_name="ai_product_drafts",
    )
    status = models.CharField(
        max_length=20, choices=STATUS_CHOICES, default=STATUS_DRAFT
    )

    title = models.CharField(max_length=300)
    description = models.TextField(help_text="Short product description")
    details_description = models.TextField(
        help_text="Structured long-form product details"
    )
    category = models.ForeignKey(
        Categories,
        on_delete=models.SET_NULL,
        null=True,
        blank=True,
        related_name="ai_product_drafts",
    )
    condition = models.CharField(
        max_length=20, choices=CONDITION_CHOICES, default=CONDITION_NEW
    )
    tag = models.CharField(max_length=255, blank=True)
    modle = models.CharField(max_length=50, blank=True)

    price = models.PositiveIntegerField(null=True, blank=True)
    suggested_price = models.PositiveIntegerField(null=True, blank=True)
    market_min = models.PositiveIntegerField(null=True, blank=True)
    market_max = models.PositiveIntegerField(null=True, blank=True)
    market_median = models.PositiveIntegerField(null=True, blank=True)
    market_sample_size = models.PositiveIntegerField(default=0)
    currency = models.CharField(max_length=3, default="NGN")
    stock = models.PositiveIntegerField(default=10)
    discount_percent = models.PositiveIntegerField(default=0)

    image = models.FileField(upload_to="ai-listings/", blank=True, null=True)
    external_image_url = models.CharField(max_length=500, blank=True)
    image_source = models.CharField(max_length=30, blank=True, default="")
    sku = models.CharField(max_length=120, blank=True)
    bulk_batch = models.ForeignKey(
        "BulkUploadBatch",
        on_delete=models.SET_NULL,
        null=True,
        blank=True,
        related_name="drafts",
    )
    prompt = models.TextField()
    provider_used = models.CharField(max_length=40, blank=True)
    ai_note = models.TextField(blank=True)
    ai_payload = models.JSONField(default=dict, blank=True)
    rejection_reason = models.TextField(blank=True)

    published_product = models.ForeignKey(
        Product,
        on_delete=models.SET_NULL,
        null=True,
        blank=True,
        related_name="ai_draft_source",
    )
    published_at = models.DateTimeField(null=True, blank=True)
    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)

    class Meta:
        ordering = ["-created_at"]

    def __str__(self):
        return f"{self.title[:60]} ({self.status})"


class BulkUploadBatch(models.Model):
    """A vendor's bulk Excel upload and its generated draft items."""

    STATUS_PENDING = "PENDING"
    STATUS_PROCESSING = "PROCESSING"
    STATUS_READY = "READY_FOR_REVIEW"
    STATUS_COMPLETED = "COMPLETED"
    STATUS_FAILED = "FAILED"
    STATUS_CHOICES = [
        (STATUS_PENDING, "Pending"),
        (STATUS_PROCESSING, "Processing"),
        (STATUS_READY, "Ready for review"),
        (STATUS_COMPLETED, "Completed"),
        (STATUS_FAILED, "Failed"),
    ]

    vendor = models.ForeignKey(
        settings.AUTH_USER_MODEL,
        on_delete=models.CASCADE,
        related_name="ai_bulk_upload_batches",
    )
    store = models.ForeignKey(
        VendorStore,
        on_delete=models.CASCADE,
        related_name="ai_bulk_upload_batches",
    )
    excel_file = models.FileField(upload_to="ai-bulk/")
    images_zip = models.FileField(upload_to="ai-bulk/", blank=True, null=True)
    status = models.CharField(
        max_length=20, choices=STATUS_CHOICES, default=STATUS_PENDING
    )
    total_rows = models.PositiveIntegerField(default=0)
    processed_rows = models.PositiveIntegerField(default=0)
    failed_rows = models.PositiveIntegerField(default=0)
    error_report = models.JSONField(default=list, blank=True)
    auto_generate_description = models.BooleanField(default=False)
    auto_suggest_price = models.BooleanField(default=False)
    auto_generate_image = models.BooleanField(default=False)
    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)

    class Meta:
        ordering = ["-created_at"]

    def __str__(self):
        return f"Bulk upload #{self.id} ({self.status})"
